<script setup lang="ts">
import { useCoursePointWithdrawals, type CoursePointWithdrawal } from '~/composables/useCoursePointWithdrawals'
definePageMeta({ layout: 'main', middleware: ['auth', 'plearnd-admin'] })
const { adminList, adminShow, adminReview, adminApprove, adminReject, adminMarkPaid } = useCoursePointWithdrawals(); const rows = ref<CoursePointWithdrawal[]>([]); const selected = ref<CoursePointWithdrawal | null>(null); const status = ref(''); const search = ref(''); const loading = ref(false); const note = ref(''); const reason = ref(''); const reference = ref(''); const proof = ref<File | null>(null); const message = ref('')
const load = async () => { loading.value = true; try { const r = await adminList({ status: status.value || undefined, purpose: search.value || undefined, per_page: 20 }); rows.value = r.data } finally { loading.value = false } }; onMounted(load)
const open = async (r: CoursePointWithdrawal) => { const x = await adminShow(r.id); selected.value = x.data }; const refresh = async () => { await load(); if (selected.value) await open(selected.value) }; const act = async (fn: () => Promise<any>) => { try { await fn(); message.value = 'ดำเนินการสำเร็จ'; await refresh() } catch (e: any) { message.value = e.data?.message || 'ดำเนินการไม่สำเร็จ' } }
const paid = () => { if (!selected.value) return; const f = new FormData(); if (reference.value) f.append('payment_reference', reference.value); if (proof.value) f.append('proof', proof.value); return act(() => adminMarkPaid(selected.value!.id, f)) }; const label = (s: string) => ({ pending: 'รอดำเนินการ', reviewing: 'กำลังตรวจสอบ', approved: 'อนุมัติแล้ว', paid: 'โอนแล้ว', rejected: 'ปฏิเสธ', cancelled: 'ยกเลิก' }[s] || s)
</script>
<template><div class="mx-auto max-w-7xl space-y-6 p-6"><div class="flex items-center justify-between"><h1 class="text-2xl font-bold">{{ $t('withdrawal.title') }}</h1><NuxtLink to="/courses" class="text-primary-600">หน้าหลักคอร์ส</NuxtLink></div><div v-if="message" class="rounded-xl bg-slate-100 p-4">{{ message }}</div><div class="flex gap-3"><select v-model="status" class="rounded-lg border p-3" @change="load"><option value="">ทุกสถานะ</option><option v-for="s in ['pending','reviewing','approved','paid','rejected','cancelled']" :key="s" :value="s">{{ label(s) }}</option></select><input v-model="search" class="rounded-lg border p-3" placeholder="ค้นหาวัตถุประสงค์" @keyup.enter="load" /><button class="rounded-lg bg-primary-600 px-4 text-white" @click="load">ค้นหา</button></div><div class="overflow-hidden rounded-2xl bg-white shadow dark:bg-slate-800"><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 dark:bg-slate-700"><tr><th class="p-4">ID</th><th class="p-4">คอร์ส</th><th class="p-4">ผู้ขอ</th><th class="p-4">จำนวน</th><th class="p-4">สถานะ</th><th class="p-4">วันที่ขอ</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id" class="cursor-pointer border-t hover:bg-slate-50 dark:border-slate-700" @click="open(r)"><td class="p-4">#{{ r.id }}</td><td class="p-4">{{ r.course?.name || r.course_id }}</td><td class="p-4">{{ r.requester?.name }}</td><td class="p-4">{{ r.amount.toLocaleString() }}</td><td class="p-4">{{ label(r.status) }}</td><td class="p-4">{{ new Date(r.requested_at).toLocaleString() }}</td></tr><tr v-if="!rows.length"><td colspan="6" class="p-8 text-center">ไม่พบรายการ</td></tr></tbody></table></div></div><aside v-if="selected" class="fixed inset-y-0 right-0 z-20 w-full max-w-md overflow-y-auto bg-white p-6 shadow-2xl dark:bg-slate-800"><button class="float-right text-2xl" @click="selected = null">×</button><h2 class="mb-5 text-xl font-bold">ถอนแต้ม #{{ selected.id }}</h2><dl class="space-y-2 text-sm"><div><dt class="text-slate-500">คอร์ส / ผู้ขอ</dt><dd>{{ selected.course?.name || selected.course_id }} / {{ selected.requester.name }}</dd></div><div><dt class="text-slate-500">จำนวน / สถานะ</dt><dd>{{ selected.amount.toLocaleString() }} / {{ label(selected.status) }}</dd></div><div><dt class="text-slate-500">วัตถุประสงค์</dt><dd>{{ selected.purpose || '—' }}</dd></div><div v-for="person in [{label:'ผู้ตรวจสอบ',value:selected.reviewer?.name,time:selected.reviewed_at},{label:'ผู้อนุมัติ',value:selected.approver?.name,time:selected.approved_at},{label:'ผู้โอน',value:selected.payer?.name,time:selected.paid_at}]" :key="person.label"><dt class="text-slate-500">{{ person.label }}</dt><dd>{{ person.value || '—' }} <span v-if="person.time">({{ new Date(person.time).toLocaleString() }})</span></dd></div></dl><div class="mt-6 space-y-3"><button v-if="selected.status === 'pending'" class="w-full rounded-lg bg-primary-600 p-3 text-white" @click="act(() => adminReview(selected!.id))">รับเรื่อง</button><template v-if="selected.status === 'reviewing'"><textarea v-model="note" class="w-full rounded-lg border p-3" placeholder="หมายเหตุอนุมัติ" /><button class="w-full rounded-lg bg-emerald-600 p-3 text-white" @click="act(() => adminApprove(selected!.id, note))">อนุมัติ</button><textarea v-model="reason" class="w-full rounded-lg border p-3" placeholder="เหตุผลปฏิเสธ (จำเป็น)" /><button :disabled="!reason.trim()" class="w-full rounded-lg bg-red-600 p-3 text-white" @click="act(() => adminReject(selected!.id, reason))">ปฏิเสธ</button></template><template v-if="selected.status === 'approved'"><input v-model="reference" class="w-full rounded-lg border p-3" placeholder="เลขอ้างอิงการโอน (ถ้ามี)" /><input type="file" class="w-full" @change="proof = ($event.target as HTMLInputElement).files?.[0] || null" /><button class="w-full rounded-lg bg-emerald-600 p-3 text-white" @click="paid">บันทึกโอนแล้ว</button></template></div></aside></div></template>
